"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[5118],{9651(e,t,s){s.r(t),s.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>d,frontMatter:()=>a,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"stoicism/epictetus/discourses/book-4/index","title":"Discourses \u2014 Book 4","description":"Book 4","source":"@site/docs/stoicism/epictetus/discourses/book-4/index.md","sourceDirName":"stoicism/epictetus/discourses/book-4","slug":"/stoicism/epictetus/discourses/book-4/","permalink":"/justinus/docs/stoicism/epictetus/discourses/book-4/","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"title":"Discourses \u2014 Book 4","sidebar_position":1},"sidebar":"philosophersSidebar","previous":{"title":"Book 3, Ch. 26","permalink":"/justinus/docs/stoicism/epictetus/discourses/book-3/discourses-book-3-chapter-26"},"next":{"title":"Book 4, Ch. 1","permalink":"/justinus/docs/stoicism/epictetus/discourses/book-4/discourses-book-4-chapter-1"}}');var i=s(4848),n=s(8453);const a={title:"Discourses \u2014 Book 4",sidebar_position:1},r="Discourses",h={},c=[{value:"Book 4",id:"book-4",level:2},{value:"Sonnet 4.6 Summary",id:"sonnet-46-summary",level:2}];function l(e){const t={em:"em",h1:"h1",h2:"h2",header:"header",p:"p",strong:"strong",...(0,n.R)(),...e.components},{Details:s}=t;return s||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Details",!0),(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)("div",{style:{textAlign:"center"},children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"discourses",children:"Discourses"})}),(0,i.jsx)(t.h2,{id:"book-4",children:"Book 4"})]}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.em,{children:"Translated by P.E. Matheson (Oxford: Clarendon Press, 1916)"})}),"\n",(0,i.jsxs)(s,{open:!0,children:[(0,i.jsx)("summary",{children:"Sonnet 4.6 Summary"}),(0,i.jsx)(t.h2,{id:"sonnet-46-summary",children:"Sonnet 4.6 Summary"}),(0,i.jsx)(t.p,{children:"Book 4 is the culmination of the Discourses. The framework established in Book 1, diagnosed as unmet in Book 2, and trained toward in Book 3 here arrives at its final statement. The tone is calmer than Book 3 \u2014 less impatient, more assured \u2014 as if Epictetus has said everything corrective that needs saying and is now drawing the full portrait of what the completed work looks like."}),(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Freedom is the book's organizing concept"}),", announced in the massive opening chapter and never really dropped. The definition established there governs everything that follows: freedom is the condition of living as you will, unhindered and uncompelled, which is only achievable by the person who has placed good and evil entirely within the will. Every other conception of freedom \u2014 legal manumission, political liberty, financial independence \u2014 is shown to be a change of masters rather than actual freedom. The rich man, the senator, the man who fears illness, the man who craves a particular woman \u2014 all are slaves, their masters being whatever external thing they have made the condition of their wellbeing."]}),(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"The choice between two lives"})," runs through nearly every chapter and is stated most plainly in Chs. 2 and 10: you cannot attend to both the governing principle and the consulship, cannot face both directions, cannot be both Thersites and Agamemnon. Progress requires choosing completely and paying the price of that choice \u2014 which includes losing the approval of former companions (Ch. 2), losing the comfort of preferred circumstances (Ch. 4), and losing the fantasy that external success and inner freedom are compatible (Ch. 10). The accounting must be done honestly: what am I giving up, what am I receiving in exchange, and is the exchange worth it? Usually it is, because what is received \u2014 self-respect, constancy, freedom from passion \u2014 is worth incomparably more than what is surrendered."]}),(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"The emperor and the tyrant"})," appear repeatedly as the ultimate test case, and Book 4 is notably more specific about the mechanics of political power than earlier books. Chapter 7 works through why the emperor's guards are only frightening to those who value what they can destroy. Chapter 1 catalogues in detail the ways proximity to Caesar enslaves people \u2014 the freedman elevated to Caesar's household who becomes instantly \"wise,\" the senator who grovels for appointment, the philosopher who trims his positions to avoid offense. Against all of these stands the figure of Diogenes \u2014 captured by pirates, sold as a slave, governing his purchaser's household \u2014 whose freedom was so complete that captivity changed nothing. This is not presented as heroic defiance but as the natural consequence of having nothing at stake in what any tyrant controls."]}),(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Contentment and disturbance"})," are examined from new angles in Book 4. The person who wants quiet (Ch. 4) is shown to be as enslaved as the person who wants office \u2014 both have made their peace conditional on external circumstances remaining a certain way. The person distressed at being pitied (Ch. 6) is shown to still half-believe the pitters are right \u2014 genuine conviction would make their opinion irrelevant. The person who has backslid into shamelessness (Ch. 9) is shown that the recovery is entirely in their own hands, because the mind is the most amenable thing in existence and nothing external is required to restore it."]}),(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"The performing philosopher"})," receives one more treatment in Ch. 8, but with a new emphasis on timing. The problem with those who hastily assume the philosopher's character is not just that they haven't done the work \u2014 it's that premature exposure kills what hasn't yet rooted. The seed must be buried before it grows. The student who blossoms before the root is established will be frost-bitten at the first difficulty. Euphrates was right to conceal his practice for years; Socrates never announced himself; the truly mature fruit forces its way out naturally and cannot be stopped. Impatience here is not just vanity \u2014 it is self-destruction."]}),(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"The social chapters"})," (Chs. 11, 12, 13) have a quality of practical wisdom that feels almost like the Enchiridion \u2014 concrete, direct, applicable to daily life. Keep the body clean as a consideration for others and as the natural expression of a mind that tends toward order. Maintain attention continuously, because deferring it to tomorrow is not a neutral choice but a permission slip for today's shamelessness. Guard what you confide and to whom, because trustworthiness is not established by disclosure but by the quality of a person's judgments. These closing chapters feel like a philosopher settling his affairs \u2014 making sure the practical details are covered before the work ends."]}),(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"The book's emotional register"}),' is the quietest of the four. Where Book 1 is constructive, Book 2 diagnostic, and Book 3 demanding, Book 4 has the quality of arrival. The repeated image of the free man \u2014 moving through crowds, courts, and adversity without needing anything from them, playing the game cheerfully while it lasts and stopping without regret when it ends \u2014 is no longer presented as an aspiration but as a description of what the fully trained person actually is. The final prayer of Ch. 10 \u2014 "Take it back; it was always yours; I used what you gave me and am satisfied" \u2014 functions as the Discourses\' last word on what a human life well-lived looks like. Everything before it was preparation for being able to say that and mean it.']})]})]})}function d(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}},8453(e,t,s){s.d(t,{R:()=>a,x:()=>r});var o=s(6540);const i={},n=o.createContext(i);function a(e){const t=o.useContext(n);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),o.createElement(n.Provider,{value:t},e.children)}}}]);